import type { Page, Route } from '@playwright/test'
import fixture from './fixtures/large.json' with { type: 'json' }

export const pid = fixture.pid
export const cutId = fixture.cut_id

/** Read-only replay of a 20k-word project (`web/e2e/fixtures/large.json`, generated by
 * `packages/post_api/tests/fixtures/gen_e2e_fixture.py --large`) for the scroll-performance
 * test -- no ops/undo/derive here, just the paged `/words` endpoint the real server also
 * pages (`packages/post_api/post_api/routes/transcripts.py`, MAX_PAGE=2000). */
export async function mockLargeApi(page: Page) {
  const allWords = fixture.words.words

  await page.route('**/api/**', async (route: Route) => {
    const req = route.request()
    const url = new URL(req.url())
    const path = url.pathname
    const method = req.method()

    if (path === `/api/projects/${pid}/shoots`) return route.fulfill({ json: fixture.shoots })
    if (path === `/api/projects/${pid}/cuts` && method === 'GET') return route.fulfill({ json: fixture.cutList })
    if (path === `/api/projects/${pid}/cuts/${cutId}` && method === 'GET') return route.fulfill({ json: fixture.cut })
    if (path === `/api/projects/${pid}/cuts/${cutId}/timeline`) return route.fulfill({ json: fixture.timeline })
    if (path === `/api/projects/${pid}/transcripts/${fixture.transcript_id}/suggestions`) return route.fulfill({ json: [] })
    if (path === `/api/projects/${pid}/transcripts/${fixture.transcript_id}` && method === 'GET') return route.fulfill({ json: fixture.transcript })
    if (path === `/api/projects/${pid}/events`) return route.abort()
    if (path.startsWith(`/api/projects/${pid}/media/`)) return route.abort()
    // T30e: the top-bar Decisions view polls this on every mount -- stub it out so it
    // doesn't fall through to a real network request.
    if (path === `/api/projects/${pid}/cuts/${cutId}/decisions` && method === 'GET') {
      return route.fulfill({ json: { rows: [], counts: { pick: 0, approve: 0, failed: 0, waiting_on: 0 } } })
    }

    if (path === `/api/projects/${pid}/transcripts/${fixture.transcript_id}/words`) {
      const offset = Number(url.searchParams.get('offset') ?? '0')
      const limit = Number(url.searchParams.get('limit') ?? '500')
      return route.fulfill({
        json: {
          transcript_id: fixture.transcript_id, total: allWords.length, offset, limit,
          words: allWords.slice(offset, offset + limit),
        },
      })
    }

    return route.continue()
  })
}
